@app.route("/api/2fa/setup", methods=["POST"])
def api_2fa_setup():
    token = request.headers.get("Authorization", "").replace("Bearer ", "")
    user = db.get_user_by_token(token)
    if not user:
        return jsonify({"error": "Unauthorized"}), 401
    data = request.get_json(silent=True) or {}
    method = data.get("method", "email")
    try:
        result = tfa.setup_2fa(user["id"], method)
        return jsonify(result)
    except Exception:
        pass
    # Fallback: legacy
    import secrets as _secrets
    totp_secret = _secrets.token_hex(16)
    conn = db.get_db()
    conn.execute("UPDATE users SET totp_secret=%s, two_fa_method=%s WHERE id=%s", (totp_secret, method, user["id"]))
    conn.commit()
    conn.close()
    return jsonify({"ok": True, "message": f"2FA setup initiated via {method}. Complete verification to activate."})

@app.route("/api/2fa/enable", methods=["POST"])
def api_2fa_enable():
    token = request.headers.get("Authorization", "").replace("Bearer ", "")
    user = db.get_user_by_token(token)
    if not user:
        return jsonify({"error": "Unauthorized"}), 401
    data = request.get_json(silent=True) or {}
    otp = data.get("otp", "")
    try:
        result = tfa.verify_and_enable(user["id"], otp)
        if result.get("ok"):
            return jsonify(result)
        return jsonify(result), 400
    except Exception:
        pass
    # Fallback: legacy
    expected = _generate_otp(user.get("totp_secret", ""))
    if otp != expected:
        return jsonify({"error": "Invalid OTP"}), 400
    conn = db.get_db()
    conn.execute("UPDATE users SET two_fa_enabled=1 WHERE id=%s", (user["id"],))
    conn.commit()
    conn.close()
    return jsonify({"ok": True, "message": "2FA enabled successfully."})

